package ktanesolver.module.modded.regular.countdown;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class CountdownSolverTest{private final CountdownSolver solver=new CountdownSolver();
	@Test void findsAndExecutesLegalSolution(){List<Integer>numbers=List.of(25,4,75,1,2,3);CountdownOutput out=solve(new CountdownInput(175,numbers));assertThat(out.operations()).isNotEmpty();assertThat(simulate(numbers,out.operations())).contains(175);assertThat(out.operations()).allSatisfy(op->{assertThat(op.result()).isBetween(0,9999);if(op.operator().equals("/"))assertThat(op.left()%op.right()).isZero();});}
	@Test void makesAtLeastOneCalculationWhenTargetIsAlreadyShown(){CountdownOutput out=solve(new CountdownInput(100,List.of(100,75,50,25,1,1)));assertThat(out.operations()).hasSize(1);assertThat(out.operations().getFirst().result()).isEqualTo(100);}
	@Test void rejectsInvalidRound(){assertThat(solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new CountdownInput(99,List.of(1,2,3,4,5,6)))).isInstanceOf(SolveFailure.class);assertThat(solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new CountdownInput(500,List.of(1,2,3)))).isInstanceOf(SolveFailure.class);}
	@SuppressWarnings("unchecked")private CountdownOutput solve(CountdownInput input){return((SolveSuccess<CountdownOutput>)solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),input)).output();}private static List<Integer>simulate(List<Integer>start,List<CountdownOutput.Operation>operations){List<Integer>values=new ArrayList<>(start);for(var op:operations){assertThat(values.remove(Integer.valueOf(op.left()))).isTrue();assertThat(values.remove(Integer.valueOf(op.right()))).isTrue();values.add(op.result());}return values;}}
